import{_ as t,o as d,c as a,a2 as l}from"./chunks/framework.CWWEQfK7.js";const m=JSON.parse('{"title":"参与开发前先读这里","description":"了解六个仓库的边界、推荐修改顺序和交付前必须完成的检查。","frontmatter":{"page_id":"development-index","title":"参与开发前先读这里","description":"了解六个仓库的边界、推荐修改顺序和交付前必须完成的检查。"},"headers":[],"relativePath":"development/index.md","filePath":"development/index.md","lastUpdated":1786627803000}'),r={name:"development/index.md"};function i(o,e,n,h,c,p){return d(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="参与开发前先读这里" tabindex="-1">参与开发前先读这里 <a class="header-anchor" href="#参与开发前先读这里" aria-label="Permalink to &quot;参与开发前先读这里&quot;">​</a></h1><p>Ershu 的业务代码分成五个模块，另有一个同名组合仓库用于本地联调、基础设施和跨模块验收。开始修改前，先确认需求属于哪个模块，再只打开必要边界。</p><h2 id="六个仓库分别负责什么" tabindex="-1">六个仓库分别负责什么？ <a class="header-anchor" href="#六个仓库分别负责什么" aria-label="Permalink to &quot;六个仓库分别负责什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>仓库</th><th>职责</th><th>不应承担的职责</th></tr></thead><tbody><tr><td><code>core</code></td><td>数据模型、数据库升级、权限、运行状态、检索与共享契约</td><td>不监听 HTTP，不启动后台任务</td></tr><tr><td><code>api</code></td><td>HTTP 路由、网页认证、管理操作、Cron 与 Webhook 入口</td><td>不直接执行分析任务</td></tr><tr><td><code>worker</code></td><td>领取任务、准备只读工作区、提取事实、生成文档与索引</td><td>不暴露面向用户的管理 API</td></tr><tr><td><code>mcp</code></td><td>认证并提供只读 MCP 查询工具</td><td>不修改项目、仓库或运行状态</td></tr><tr><td><code>frontend</code></td><td>登录、项目工作区、分析跟踪、文档、搜索、关系图和管理页面</td><td>不绕过 API 直接访问数据库</td></tr><tr><td><code>ershu</code></td><td>固定模块组合、本地基础设施、跨仓测试和发布边界</td><td>不复制五个模块的业务实现</td></tr></tbody></table><p>API、Worker 和 MCP 依赖 Core，但彼此不应通过源码导入耦合。前端只通过 HTTP 与 API 通信。跨模块行为需要在组合仓库做一次完整验收。</p><h2 id="修改一项功能的推荐顺序" tabindex="-1">修改一项功能的推荐顺序 <a class="header-anchor" href="#修改一项功能的推荐顺序" aria-label="Permalink to &quot;修改一项功能的推荐顺序&quot;">​</a></h2><ol><li>写清楚对外行为和失败方式，找到当前契约或测试。</li><li>如果涉及共享数据或权限，先修改 Core 的模型、服务和升级记录。</li><li>在唯一负责的进程中实现入口：HTTP 放 API，分析放 Worker，只读智能体查询放 MCP。</li><li>前端调用现有 API 客户端，并处理加载、空状态、错误和权限不足。</li><li>先跑模块自己的格式、类型、测试和构建检查，再跑组合仓库的边界与流程测试。</li><li>更新与行为直接相关的文档，标明验证方法和成功结果。</li></ol><h2 id="常见开发入口" tabindex="-1">常见开发入口 <a class="header-anchor" href="#常见开发入口" aria-label="Permalink to &quot;常见开发入口&quot;">​</a></h2><ul><li>需要理解调用关系：阅读<a href="/development/architecture">整体架构与数据流</a>。</li><li>第一次搭环境：阅读<a href="/development/local-setup">搭建本地开发环境</a>。</li><li>增加设置：阅读<a href="/development/configuration">理解配置加载流程</a>。</li><li>增加 HTTP 端点：阅读<a href="/development/add-api">新增 API</a>。</li><li>增加工具或分析阶段：阅读<a href="/development/extend-mcp-worker">扩展 MCP 与 Worker</a>。</li><li>增加页面：阅读<a href="/development/frontend">开发前端页面</a>。</li><li>准备提交：阅读<a href="/development/quality">质量与提交流程</a>。</li></ul><h2 id="提交前的最低要求" tabindex="-1">提交前的最低要求 <a class="header-anchor" href="#提交前的最低要求" aria-label="Permalink to &quot;提交前的最低要求&quot;">​</a></h2><ul><li>变更只落在拥有该职责的模块，必要的共享契约有配套测试；</li><li>新配置明确类型、默认值、是否可在线覆盖及错误反馈；</li><li>新 API 有认证、权限、输入和错误路径测试；</li><li>长任务可以恢复查看，不依赖浏览器连接一直存在；</li><li>文档只描述当前实现，命令结果来自实际执行；</li><li>每个仓库自己的检查通过，跨仓改动再通过组合仓测试。</li></ul>',11)])])}const P=t(r,[["render",i]]);export{m as __pageData,P as default};
